// Spherical data geometry. All distances are surface distances, independent of rendering.
export const PLANET_RADIUS=42,HALF=Math.PI*PLANET_RADIUS,POLE=HALF/2,SOLAR_DAY=160,YEAR=SOLAR_DAY*24;
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const wrap=x=>((x+HALF)%(2*HALF)+2*HALF)%(2*HALF)-HALF;
export function normalize(x,z){while(z>POLE||z< -POLE){z=z>POLE?2*POLE-z:-2*POLE-z;x+=HALF;}return{x:wrap(x),z};}
export function normal(x,z){const a=z/PLANET_RADIUS,b=x/PLANET_RADIUS,c=Math.cos(a);return{x:c*Math.sin(b),y:Math.sin(a),z:c*Math.cos(b)};}
export function xyz(x,z,h=0){const n=normal(x,z),r=PLANET_RADIUS+h;return{x:n.x*r,y:n.y*r,z:n.z*r};}
export function coordinates(p){return{x:Math.atan2(p.x,p.z)*PLANET_RADIUS,z:Math.asin(clamp(p.y/Math.hypot(p.x,p.y,p.z),-1,1))*PLANET_RADIUS};}
export function delta(a,b){return{x:wrap(b.x-a.x)*Math.max(.015,Math.cos((a.z+b.z)/2/PLANET_RADIUS)),z:b.z-a.z};}
export function distance(a,b){const p=(b.z-a.z)/PLANET_RADIUS,q=wrap(b.x-a.x)/PLANET_RADIUS,h=Math.sin(p/2)**2+Math.cos(a.z/PLANET_RADIUS)*Math.cos(b.z/PLANET_RADIUS)*Math.sin(q/2)**2;return 2*PLANET_RADIUS*Math.asin(Math.sqrt(clamp(h,0,1)));}
export function move(x,z,east,north){const d=Math.hypot(east,north);if(d<1e-12)return normalize(x,z);const a=z/PLANET_RADIUS,b=x/PLANET_RADIUS,h=Math.atan2(east,north),arc=d/PLANET_RADIUS,a2=Math.asin(clamp(Math.sin(a)*Math.cos(arc)+Math.cos(a)*Math.sin(arc)*Math.cos(h),-1,1)),b2=b+Math.atan2(Math.sin(h)*Math.sin(arc)*Math.cos(a),Math.cos(arc)-Math.sin(a)*Math.sin(a2));return normalize(b2*PLANET_RADIUS,a2*PLANET_RADIUS);}
export const CONTINENTS=[{name:'Auralia',x:0,z:12,rx:37,rz:34},{name:'Nimbara',x:91,z:-17,rx:33,rz:30},{name:'Umbriel',x:-89,z:-7,rx:30,rz:39},{name:'Islas del Alba',x:49,z:-40,rx:14,rz:13}];
export function geography(x,z){const n=normal(x,z);let best=-9,region=0;for(let i=0;i<CONTINENTS.length;i++){const c=CONTINENTS[i],dx=wrap(x-c.x)*Math.cos((z+c.z)*.5/PLANET_RADIUS),dz=z-c.z,a=Math.atan2(dz,dx),edge=1+.13*Math.sin(a*5+i)+.08*Math.cos(a*9-i),h=(1-Math.sqrt((dx/c.rx)**2+(dz/c.rz)**2)/edge)*3.8;if(h>best){best=h;region=i;}}const height=best+Math.sin(n.x*19+n.z*7)*Math.cos(n.z*17+n.y*8)*.28+Math.sin(n.y*31+n.x*13)*.1,c=CONTINENTS[region],dz=z-c.z,riverX=c.x+Math.sin(dz*.12+region)*4+dz*.17,riverDistance=Math.abs(wrap(x-riverX))*Math.max(.08,Math.cos(z/PLANET_RADIUS)),river=height>.08&&height<3.65&&Math.abs(dz)<c.rz*.98&&riverDistance<.5,latitude=Math.abs(z/PLANET_RADIUS),moisture=clamp(.56+.21*Math.sin(n.x*6-n.z*4)-.13*Math.abs(Math.sin(n.y*5))+(riverDistance<4?.26:0),.12,.95),biome=height<0?'Océano':river?'Río':latitude>1.1?'Tundra':height>2.9?'Sierra':moisture<.42?'Sabana':moisture>.68?'Bosque húmedo':'Pradera';return{height:height<0?Math.max(-1.9,height*.36):river?Math.max(.06,height-.22):height,land:height>=0,water:height<0||river,river,riverDistance,region,latitude,moisture,biome};}
export function terrain(x,z){const g=geography(x,z);return g.land?g.height:.04;}
export const inWater=(x,z)=>geography(x,z).water,pondAt=(x,z)=>inWater(x,z)?0:-1,walkable=(x,z)=>Number.isFinite(x+z)&&Math.abs(z)<=POLE&&!inWater(x,z);
export function sunDirection(t){const a=t/SOLAR_DAY*Math.PI*2,d=Math.sin(t/YEAR*Math.PI*2)*.409;return{x:Math.sin(a)*Math.cos(d),y:Math.sin(d),z:Math.cos(a)*Math.cos(d)};}
export function climateAt(x,z,time,climate={temperature:22,moisture:65},rain=0){const geo=geography(x,z),n=normal(x,z),sun=sunDirection(time),incidence=n.x*sun.x+n.y*sun.y+n.z*sun.z,light=clamp(incidence*1.35,0,1),annual=Math.sin(time/YEAR*Math.PI*2)*Math.sin(z/PLANET_RADIUS)*10,temperature=climate.temperature+7-geo.latitude*19-geo.height*1.1+annual+incidence*5,moisture=clamp(geo.moisture*climate.moisture/65+(rain>0?.15:0)-light*.055,.06,1);return{...geo,light,incidence,temperature,moisture,daylight:incidence>0,phase:incidence>.18?'Día':incidence>-.13?'Crepúsculo':'Noche',localHour:((time/SOLAR_DAY*24-x/HALF*12+12)%24+24)%24};}
export function adaptation(c,e){const g=c.dna.traits,coat=g.insulation??.5,feet=g.webbing??.3,night=g.nocturnal??.5,thermal=Math.abs(e.temperature-(29-coat*20))/35;return{thermal,locomotion:clamp(.8+g.legs*.18+(e.river?feet*.32:e.biome==='Sierra'?g.legs*.1:0)-(g.width-1)*.09,.6,1.5),cost:1+thermal*.6+Math.max(0,g.legs-1)*.12+Math.max(0,g.neck-1)*.07+feet*(e.water?0:.05),activity:e.daylight?1-night*.55:.45+night*.65};}
